 notes: {
  "Sicilian Defense": "Czarne odpowiadają na 1.e4 ruchem 1...c5 i nie naśladują białych w centrum. To najczęściej grana odpowiedź na posunięcie piona królewskiego na każdym poziomie, prowadząca do ostrych, niezrównoważonych pozycji, w których obie strony grają o wygraną.",
  "French Defense": "1...e6 buduje solidny łańcuch pionów i zaprasza białe do przesunięcia się naprzód. Czarne godzą się na biernego gońca białopolowego w zamian za mocną strukturę i wyraźną kontrgrę na skrzydle hetmańskim.",
  "Caro-Kann Defense": "1...c6 przygotowuje ...d5 bez zamykania gońca białopolowego, co jest główną praktyczną różnicą w porównaniu z obroną francuską. Solidna i słynna z tego, że trudno ją rozbić.",
  "Ruy Lopez": "1.e4 e5 2.Nf3 Nc6 3.Bb5 od razu naciska na skoczka broniącego e5. Jeden z najstarszych debiutów wciąż granych na najwyższym poziomie, bogaty w długofalowe plany pozycyjne.",
  "Italian Game": "3.Bc4 celuje gońcem w pole f7. Prowadzi albo do spokojnego manewrowania w Giuoco Pianissimo, albo do naprawdę ostrej gry w gambicie Evansa.",
  "Queen's Gambit": "1.d4 d5 2.c4 oferuje piona, żeby odciągnąć centrum czarnych. To nie jest prawdziwy gambit: pion zwykle wraca, a białe zyskują trwałą obecność w centrum.",
  "Queen's Gambit Declined": "Czarne trzymają centrum ruchem ...e6, zamiast brać na c4. Klasyczny, solidny wybór, który rozstrzygnął wiele meczów o mistrzostwo świata.",
  "King's Indian Defense": "Czarne pozwalają białym na duże centrum, a potem kontratakują, zwykle ruchem ...e5 i szturmem pionów na skrzydle królewskim. Dynamiczna i obosieczna.",
  "Nimzo-Indian Defense": "3...Bb4 wiąże skoczka i walczy o centrum raczej figurami niż pionami. Ulubiona obrona graczy pozycyjnych.",
  "English Opening": "1.c4 kontroluje d5 ze skrzydła i często przechodzi w inne debiuty. Elastyczny i trudny do przygotowania.",
  "Scandinavian Defense": "1...d5 od razu rzuca wyzwanie centrum. Hetman czarnych zwykle wychodzi wcześnie, co jest mniej ryzykowne, niż się wydaje.",
  "Pirc Defense": "Czarne oddają centrum i podminowują je później figurami i pchnięciami pionów. Nowoczesny wybór w duchu hipermodernizmu.",
  "Scotch Game": "3.d4 od razu otwiera pozycję, prowadząc do wymian w centrum i do jasnej, taktycznej gry.",
  "Vienna Game": "2.Nc3 zostawia otwarte możliwości i może przejść w kilka innych systemów, często z wczesnym pchnięciem f4.",
  "London System": "Raczej ustawienie niż wariant: Bf4, e3, Nf3, c3 i Bd3. Łatwy do nauczenia i niezawodny, i właśnie dlatego tak szybko się rozpowszechnił.",
  "King's Gambit": "Białe oferują piona f, żeby rozerwać centrum. Dziewiętnastowieczne szachy w najczystszej postaci, wciąż groźne przy dobrym przygotowaniu.",
  "Slav Defense": "Czarne wspierają d5 ruchem ...c6, zostawiając otwartą przekątną gońca białopolowego. Niezwykle solidna.",
  "Grünfeld Defense": "Czarne oddają białym szerokie centrum pionowe, a potem atakują je z daleka. Ostra i wymagająca teoretycznie.",
  "Alekhine Defense": "1...Nf6 zachęca białe do gonienia skoczka i nadmiernego rozciągnięcia się. Prowokacyjna z założenia.",
  "Bird Opening": "1.f4 zdobywa przestrzeń na skrzydle królewskim kosztem osłabienia króla. Rzadki, ale całkowicie grywalny.",
  "Dutch Defense": "1...f5 zgłasza roszczenia do pola e4 i celuje w grę na skrzydle królewskim, kosztem części bezpieczeństwa króla.",
  "Réti Opening": "1.Nf3 rozwija figurę i czeka, zachowując wszystkie możliwości w centrum. Nazwany na cześć jednego z twórców szachów hipermodernistycznych.",
  "Bishop's Opening": "2.Bc4 celuje w f7, zanim wyjdą skoczki, i często przechodzi w partię wiedeńską albo włoską.",
  "Philidor Defense": "2...d6 solidnie broni e5. Bierna, ale naprawdę trudna do złamania.",
  "Petrov's Defense": "2...Nf6 kontratakuje zamiast bronić. Na najwyższym poziomie ma opinię remisowej, a wszędzie indziej świetne wyniki praktyczne.",
  "Four Knights Game": "Obie strony rozwijają się symetrycznie. Spokojna z pozoru, ale ostrzejsza, niż głosi jej opinia.",
  "Benoni Defense": "Czarne godzą się na mniej przestrzeni w zamian za przewagę pionową na skrzydle hetmańskim i otwarte linie.",
  "Modern Defense": "Czarne robią fianchetto i odkładają decyzje w centrum, żeby później wyprowadzić kontratak.",
  "Catalan Opening": "Białe łączą d4 i c4 z fianchettem na skrzydle królewskim. Goniec na g2 może naciskać przez całą partię."
 },
